<?php declare(strict_types=1);
$journalHistory=array_values(array_reverse(array_filter($service->history($periodId),static fn(array$e):bool=>in_array($e['payload']['kind'],['created','opened','account','posted','closed'],true))));if(!$journalHistory)return;
$journalPages=(int)ceil(count($journalHistory)/20);$journalRaw=$_GET['journal_history_page']??'1';$journalValid=is_string($journalRaw)&&preg_match('/\A[1-9][0-9]{0,3}\z/D',$journalRaw)&&(int)$journalRaw<=$journalPages;$journalPage=$journalValid?(int)$journalRaw:1;$journalHistoryUrl=static fn(int$n):string=>url(['view'=>'finance','tab'=>'tax','balance'=>'1','periods'=>'1','period_id'=>$periodId,'journal_history_page'=>(string)$n]);
?>
<details class="card" data-period-journal-history <?= array_key_exists('journal_history_page',$_GET)?'open':'' ?>><summary><?= e($periodText('Buchungsschritte dieses Zeitraums')) ?> (<?= count($journalHistory) ?>)</summary>
<?php if(!$journalValid): ?><p role="alert"><?= e($periodText('Verlaufsseite dieses Abschlusszeitraums vollständig auswählen.')) ?></p><a class="btn btn-outline" href="<?= e($journalHistoryUrl(1)) ?>"><?= e($periodText('Verlauf neu öffnen')) ?></a><?php else: ?>
<?php foreach(array_slice($journalHistory,($journalPage-1)*20,20)as$journalRow):$journalKind=$journalRow['payload']['kind'];$journalData=$journalRow['payload']['data'];$journalLabel=match($journalKind){'created'=>'Abschlusszeitraum angelegt','opened'=>'Anfangsbestände übernommen','account'=>'Buchungskonto ergänzt','posted'=>($journalData['entry']['reversal_of']??null)!==null?'Ursprüngliche Buchung storniert':'Zusätzliche Buchung gespeichert','closed'=>'Abschluss dieses Zeitraums bestätigt'};$journalNote=match($journalKind){'created'=>$journalData['definition']['evidence'],'posted'=>$journalData['entry']['evidence'],'account'=>implode(', ',array_column($journalData['accounts'],'name')),default=>$journalData['evidence']}; ?>
<article><h3><?= e((new DateTimeImmutable($journalRow['payload']['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i').' · '.$periodText($journalLabel)) ?></h3><p><?= e($journalNote) ?></p><a class="btn btn-outline" data-period-journal-history-link="<?= (int)$journalRow['revision'] ?>" href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','periods'=>'1','period_id'=>$periodId,'period_original'=>(string)$journalRow['revision'],'period_original_sha256'=>$journalRow['sha256']])) ?>"><?= e($periodText('Diesen ursprünglichen Ausgang lesen')) ?></a></article><?php endforeach ?>
<?php if($journalPages>1): ?><nav aria-label="<?= e($periodText('Verlauf dieses Abschlusszeitraums')) ?>"><p><?= e($periodText('Seite')) ?> <?= $journalPage ?> / <?= $journalPages ?></p><?php if($journalPage>1): ?><a class="btn btn-outline" href="<?= e($journalHistoryUrl($journalPage-1)) ?>"><?= e($periodText('Neuere Entscheidungen')) ?></a><?php endif ?><?php if($journalPage<$journalPages): ?><a class="btn btn-outline" href="<?= e($journalHistoryUrl($journalPage+1)) ?>"><?= e($periodText('Frühere Entscheidungen')) ?></a><?php endif ?></nav><?php endif ?><?php endif ?></details>
